function normalizeCfg(x){x=x&&typeof x==='object'?x:{};const t=x.tax&&typeof x.tax==='object'?x.tax:{},c=x.charge&&typeof x.charge==='object'?x.charge:{};return{tax:{enabled:t.enabled===true,mode:t.mode==='fixed'?'fixed':'percent',value:Math.max(0,Number(t.value)||0),label:String(t.label||'Pajak')},charge:{enabled:c.enabled===true,mode:c.mode==='fixed'?'fixed':'percent',value:Math.max(0,Number(c.value)||0),label:String(c.label||'Charge')}}}
async function loadPricing(force=false){if(pricingLoaded&&!force)return pricing;try{const r=await fetch(SB+'/rest/v1/tenant_site_settings_public_v1?select=transaction_settings,language_settings&tenant_id=eq.'+encodeURIComponent(TENANT)+'&limit=1',{headers:{apikey:KEY,Authorization:'Bearer '+KEY,'X-SDB-Tenant-ID':TENANT},cache:'no-store'});if(r.ok){const a=await r.json(),row=a?.[0]||{};pricing=normalizeCfg(row.transaction_settings);const lang=String(row.language_settings?.default||'id');document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';pricingLoaded=true}}catch{}return pricing}
function calc(subtotal){const c=pricing.charge,t=pricing.tax,charge=c.enabled&&c.value>0?(c.mode==='fixed'?Math.round(c.value):Math.round(subtotal*c.value/100)):0,taxBase=subtotal+charge,tax=t.enabled&&t.value>0?(t.mode==='fixed'?Math.round(t.value):Math.round(taxBase*t.value/100)):0;return{subtotal,charge,tax,total:subtotal+charge+tax,c,t}}
