    console.error("[public-runtime-fallback]",JSON.stringify({event:"runtime_asset_unavailable",status:200,mode:"rum-only",code}));
    const body=(RUM_V3+"\n;document.documentElement.dataset.rohmatRuntime='rum-only-batch1-v1';")
